// FHC Pages CMS Content Loader
// This script loads content from JSON files generated by Pages CMS into data-editable fields

(function() {
  'use strict';

  // Configuration: Map page paths to their content JSON files
  const contentConfig = {
    '/': '/content/home.json',
    '/index.html': '/content/home.json',
    '/contact/': '/content/contact.json',
    '/contact/index.html': '/content/contact.json',
    '/livestream/': '/content/livestream.json',
    '/livestream/index.html': '/content/livestream.json',
    '/media/': '/content/media.json',
    '/media/index.html': '/content/media.json',
    '/privacy/': '/content/privacy.json',
    '/privacy/index.html': '/content/privacy.json',
    '/radio/': '/content/radio.json',
    '/radio/index.html': '/content/radio.json',
    '/terms/': '/content/terms.json',
    '/terms/index.html': '/content/terms.json'
  };

  /**
   * Load and apply CMS content to the page
   */
  function loadCMSContent() {
    const currentPath = window.location.pathname;
    const contentFile = contentConfig[currentPath];

    // If no content file configured for this page, exit
    if (!contentFile) {
      console.log('FHC CMS: No content configuration for', currentPath);
      return;
    }

    // Load shared site settings first, then page-specific content
    Promise.all([
      fetch('/content/site-settings.json').then(r => r.ok ? r.json() : {}),
      fetch(contentFile).then(r => r.ok ? r.json() : {})
    ])
      .then(([sharedData, pageData]) => {
        // Merge shared settings with page data (page data takes precedence)
        const mergedData = { ...sharedData, ...pageData };
        applyContentToPage(mergedData);
        console.log('FHC CMS: Content loaded successfully');
      })
      .catch(error => {
        console.log('FHC CMS: Content not yet available or error loading:', error.message);
        // This is normal if content hasn't been created in CMS yet
        // Page will display with default HTML content
      });
  }

  /**
   * Apply content data to elements with data-editable attributes
   */
  function applyContentToPage(data) {
    // Loop through all elements with data-editable attribute
    document.querySelectorAll('[data-editable]').forEach(element => {
      const fieldName = element.getAttribute('data-editable');
      const fieldValue = data[fieldName];

      // Skip if no data for this field
      if (fieldValue === undefined || fieldValue === null) {
        return;
      }

      // Apply content based on element type and attributes
      applyContentToElement(element, fieldName, fieldValue);
    });
  }

  /**
   * Apply content to a specific element based on its type
   */
  function applyContentToElement(element, fieldName, value) {
    // Handle special cases for specific field names
    
    // Background images (hero sections)
    if (fieldName.includes('bg-image') || fieldName.includes('bg_image')) {
      element.style.backgroundImage = `url('${value}')`;
      return;
    }

    // Regular images (src attribute)
    if (element.tagName === 'IMG' || fieldName.includes('photo') || fieldName.includes('image')) {
      if (element.tagName === 'IMG') {
        element.src = value;
      } else {
        // For elements with data-editable on image fields but not IMG tags
        const img = element.querySelector('img');
        if (img) {
          img.src = value;
        }
      }
      return;
    }

    // Links (href attribute) - for social media links, email, phone, website
    if (element.tagName === 'A' && (fieldName.includes('link') || fieldName.includes('email') || fieldName.includes('phone') || fieldName.includes('website'))) {
      // Update href
      if (fieldName.includes('email')) {
        element.href = `mailto:${value}`;
      } else if (fieldName.includes('phone')) {
        element.href = `tel:${value}`;
      } else if (fieldName.includes('website')) {
        element.href = value.startsWith('http') ? value : `https://${value}`;
      } else {
        element.href = value;
      }
      
      // Don't update text content for icon-only links
      if (!element.querySelector('[uk-icon]') && !fieldName.includes('-link')) {
        element.textContent = value;
      }
      return;
    }

    // Default: update text content or innerHTML
    // Use innerHTML for fields that might contain HTML (like rich text)
    if (value.includes('<') && value.includes('>')) {
      element.innerHTML = value;
    } else {
      element.textContent = value;
    }
  }

  // Load content when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', loadCMSContent);
  } else {
    loadCMSContent();
  }

})();
